CREATE EXTENSION IF NOT EXISTS pgcrypto;
CREATE TABLE app_users (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), full_name VARCHAR(180) NOT NULL, email VARCHAR(180) NOT NULL UNIQUE, phone VARCHAR(30), password_hash VARCHAR(255) NOT NULL, status VARCHAR(30) NOT NULL DEFAULT 'PENDING', created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(), updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE TABLE communities (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), name VARCHAR(150) NOT NULL, district_name VARCHAR(120) NOT NULL, sector_name VARCHAR(120) NOT NULL, cell_name VARCHAR(120) NOT NULL, village_name VARCHAR(120) NOT NULL, status VARCHAR(30) NOT NULL DEFAULT 'ACTIVE', created_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE TABLE community_memberships (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), user_id UUID NOT NULL REFERENCES app_users(id), community_id UUID NOT NULL REFERENCES communities(id), role VARCHAR(40) NOT NULL DEFAULT 'CITIZEN', created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(), UNIQUE(user_id,community_id,role));
CREATE TABLE resources (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), community_id UUID NOT NULL REFERENCES communities(id), name VARCHAR(150) NOT NULL, category VARCHAR(40) NOT NULL, quantity NUMERIC(18,3) NOT NULL DEFAULT 0 CHECK(quantity >= 0), unit VARCHAR(30) NOT NULL, status VARCHAR(30) NOT NULL DEFAULT 'AVAILABLE', source_device_id UUID, version BIGINT NOT NULL DEFAULT 1, created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(), updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE TABLE resource_transactions (id UUID PRIMARY KEY, resource_id UUID NOT NULL REFERENCES resources(id), community_id UUID NOT NULL REFERENCES communities(id), transaction_type VARCHAR(30) NOT NULL, quantity NUMERIC(18,3) NOT NULL CHECK(quantity > 0), actor_user_id UUID REFERENCES app_users(id), device_id UUID, idempotency_key VARCHAR(120) NOT NULL UNIQUE, created_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE TABLE emergency_incidents (id UUID PRIMARY KEY, community_id UUID NOT NULL REFERENCES communities(id), reported_by UUID REFERENCES app_users(id), incident_type VARCHAR(80) NOT NULL, description TEXT, severity VARCHAR(20) NOT NULL, status VARCHAR(30) NOT NULL DEFAULT 'REPORTED', latitude DOUBLE PRECISION, longitude DOUBLE PRECISION, created_at TIMESTAMPTZ NOT NULL DEFAULT NOW());
CREATE TABLE sync_events (id UUID PRIMARY KEY, community_id UUID NOT NULL REFERENCES communities(id), device_id UUID NOT NULL, entity_type VARCHAR(80) NOT NULL, entity_id UUID NOT NULL, operation VARCHAR(30) NOT NULL, payload JSONB NOT NULL, event_version BIGINT NOT NULL DEFAULT 1, event_created_at TIMESTAMPTZ NOT NULL, received_at TIMESTAMPTZ NOT NULL DEFAULT NOW(), status VARCHAR(30) NOT NULL DEFAULT 'RECEIVED');
CREATE INDEX idx_resources_community ON resources(community_id);
CREATE INDEX idx_resources_category ON resources(category);
CREATE INDEX idx_incidents_community_status ON emergency_incidents(community_id,status);
CREATE INDEX idx_sync_events_community_received ON sync_events(community_id,received_at);
CREATE INDEX idx_memberships_user ON community_memberships(user_id);
